const nl=s=>cleanText(s||'—').replace(/\n/g,'<br>');
const digits=s=>String(s??'').replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c)));
const norm=s=>digits(s).trim().toLowerCase().replace(/\s+/g,' ');
const today=()=>dateID(new Date());
const faDate=(dt,opts={year:'numeric',month:'long',day:'numeric'})=>new Intl.DateTimeFormat('fa-IR-u-ca-persian',opts).format(new Date(dt));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const dateID=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const isoNow=()=>new Date().toISOString();
const uid=()=>String(Date.now())+'-'+Math.random().toString(36).slice(2,8);
function defaults(){return {schema:1,created:isoNow(),completed:{python:[],math:[]},assessments:{},sessions:[],notes:{},research:[],skills:{},checks:{},lastPlace:{track:'python',id:'py01'},lessonDrafts:{},settings:{pythonCap:60,mainStart:'14:00',morningMin:60,eveningMin:150}};}
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&s.schema===1&&s.completed&&s.sessions&&s.research&&s.settings){return {...defaults(),...s}}}catch(e){console.warn('Saved data invalid',e)}return defaults()}
let state=load(),view='dashboard',activeLesson=null,activeResearch=null,compareIds=[],searchText='',researchFilter='',toastTimer=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){alert('ذخیره‌سازی مرورگر در دسترس نیست یا فضای آن پر است. از اطلاعات فعلی خروجی بگیر.');return false}}
function courseOf(t){return COURSE[t]}
function passed(t,id){return (state.completed[t]||[]).includes(id)}
function unlocked(t,index){return index===0||passed(t,COURSE[t].lessons[index-1].id)}
function nextLesson(t){return COURSE[t].lessons.find((l,i)=>unlocked(t,i)&&!passed(t,l.id)) || COURSE[t].lessons.at(-1)}
function progress(t){return Math.round(100*(state.completed[t]||[]).length/COURSE[t].lessons.length)}
function dayMinutes(t){return state.sessions.filter(s=>s.track===t&&s.date===today()).reduce((n,s)=>n+(Number(s.minutes)||0),0)}
function allMinutes(){return state.sessions.reduce((n,s)=>n+(Number(s.minutes)||0),0)}
function weekStart(d=new Date()){let x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()-((x.getDay()+1)%7));return x;}
function weekKey(){return dateID(weekStart())}
function slotKey(day,slot){return weekKey()+'|'+day+'|'+slot}
function showToast(message){const n=document.getElementById('toast');n.textContent=message;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3300)}
function currentDayPlan(){return WEEK.find(x=>x.day===new Date().getDay())}
function getDayDate(day){const base=weekStart();base.setDate(base.getDate()+((day+1)%7));return base}
function pctBar(n){return `<div class="progress-track"><div class="progress-fill" style="width:${clamp(n,0,100)}%"></div></div>`}
function badge(text,cl=''){return `<span class="pill ${cl}">${cleanText(text)}</span>`}
function safeHref(s){try{const url=new URL(s);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}}
function navigate(v){view=v;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})}
function render(){const t=titles[view]||titles.dashboard;document.getElementById('page-eyebrow').textContent=t[0];document.getElementById('page-title').textContent=t[1];document.getElementById('today-date').textContent=faDate(new Date(),{weekday:'long',month:'long',day:'numeric'});document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.nav===(['lesson'].includes(view)?activeLesson?.track:view==='researchEdit'||view==='compare'?'research':view)));const p=document.getElementById('page-root');let out='';switch(view){case'dashboard':out=renderDashboard();break;case'python':case'math':out=renderCourse(view);break;case'lesson':out=renderLesson();break;case'weekly':out=renderWeekly();break;case'research':out=renderResearch();break;case'researchEdit':out=renderResearchEdit();break;case'compare':out=renderCompare();break;case'skills':out=renderSkills();break;case'history':out=renderHistory();break;default:out=renderDashboard()}p.innerHTML=out;}
function renderDashboard(){
 const p=currentDayPlan(),doneW=Object.keys(state.checks).filter(k=>k.startsWith(weekKey()+'|')&&state.checks[k]).length,totalW=21;
 const finished=(state.completed.python||[]).length+(state.completed.math||[]).length;
 const nextPy=nextLesson('python'),nextMa=nextLesson('math');
 const allDone=COURSE.python.lessons.every(l=>passed('python',l.id))&&COURSE.math.lessons.every(l=>passed('math',l.id));
 const resume=state.lastPlace&&COURSE[state.lastPlace.track]?.lessons.find(l=>l.id===state.lastPlace.id)?state.lastPlace:{track:'python',id:nextPy.id};
 const rem=Math.max(0,60-dayMinutes('python'));
 return `<section class="hero"><div class="hero-copy"><div class="hero-label">نقشهٔ رشدِ عمیق و مرحله‌ای</div><h2>هر روز یک گام، با فهمی که می‌ماند.</h2><p>فهم چرایی و چگونگی، شبیه‌سازی ذهنی، تمرین و شواهد پژوهشی را در یک مسیر پیوسته نگه دار. هیچ پیش‌نیازی بدون ارزیابی باز نمی‌شود.</p><div class="hero-actions"><button class="button button-light" data-action="open-lesson" data-track="${resume.track}" data-id="${resume.id}">↗ ${allDone?'مرور آخرین جلسه':'ادامه از آخرین مرحله'}</button><button class="button button-ghost-light" data-nav="weekly">برنامه این هفته</button></div></div><div class="hero-mark"><div style="text-align:center"><strong>${finished}</strong><small style="display:block">مرحلهٔ طی‌شده</small></div></div></section>
 <section class="metrics"><div class="metric"><div class="metric-ico">∑</div><div><strong>${finished} <span style="font-size:12px;color:#92a1ae">/ ${COURSE.python.lessons.length+COURSE.math.lessons.length}</span></strong><small>درس تأییدشده</small></div></div><div class="metric"><div class="metric-ico green">◷</div><div><strong>${allMinutes()}</strong><small>دقیقهٔ ثبت‌شده</small></div></div><div class="metric"><div class="metric-ico warm">◉</div><div><strong>${state.research.length}</strong><small>پروندهٔ پژوهشی</small></div></div><div class="metric"><div class="metric-ico pink">✓</div><div><strong>${doneW} <span style="font-size:12px;color:#92a1ae">/ ${totalW}</span></strong><small>بخش انجام‌شده در هفته</small></div></div></section>
 <section class="section grid-main"><div class="card"><div class="card-title"><h3>مسیرهای آموزشی</h3>${badge('ارزیابی مرحله‌ای','green')}</div>${['python','math'].map(t=>{const c=COURSE[t],n=nextLesson(t),done=(state.completed[t]||[]).length;return `<div class="track-card"><div class="track-title"><strong>${t==='python'?'⌘':'∑'} ${c.name}</strong>${badge(progress(t)+'٪','')}</div>${pctBar(progress(t))}<div class="track-meta"><div class="next-title">${done===c.lessons.length?'تمام مراحل تکمیل شده':`گام بعد: ${cleanText(n.title)}`}</div><button class="button button-outline button-sm" data-action="open-lesson" data-track="${t}" data-id="${n.id}">${done===c.lessons.length?'مرور':'شروع / ادامه'}</button></div></div>`}).join('')}<div class="today-note">⏱ امروز برای پایتون <strong>${dayMinutes('python')}</strong> دقیقه ثبت شده؛ از سقف ۶۰ دقیقه، <strong>${rem}</strong> دقیقه باقی است.</div></div>
 <div class="card"><div class="card-title"><h3>برنامهٔ امروز: ${p.name}</h3>${badge('شروع ۱۴:۰۰','amber')}</div><div class="check-list">${renderCheck(p,'morning',true)}${renderCheck(p,'main',true)}${renderCheck(p,'evening',true)}</div><div class="notice"><strong>تمرکز عصر:</strong> ${cleanText(p.evening)}. در صورت خستگی، فقط بخش ضروری ۲ ساعته را انجام بده.</div><button class="button button-muted" data-nav="weekly" style="width:100%">مشاهدهٔ همهٔ روزها</button></div></section>
 <section class="section grid-main"><div class="card"><div class="card-title"><h3>آخرین فعالیت‌ها</h3><button class="subaction" data-nav="history">تاریخچه کامل</button></div>${state.sessions.length?state.sessions.slice(-4).reverse().map(s=>`<div class="check-line" style="background:white"><div style="flex:1"><strong>${cleanText(sessionTitle(s))}</strong><div class="mini muted">${faDate(s.timestamp)} • ${cleanText(s.kind||'جلسه')}</div></div>${badge((Number(s.minutes)||0)+' دقیقه')}</div>`).join(''):`<div class="empty" style="padding:25px"><div class="empty-symbol">◷</div><p>هنوز جلسه‌ای ثبت نشده است. با تمرین و ارزیابی نخستین سابقهٔ یادگیری شکل می‌گیرد.</p></div>`}</div>
 <div class="card"><div class="card-title"><h3>دفتر پژوهش میان‌رشته‌ای</h3>${badge('نقد شواهد','')}</div><p class="small muted">برای هر مقاله، روش، مجموعه‌داده، شواهد، محدودیت‌ها و خطر نشت داده را ثبت کن؛ دو پژوهش را کنار هم بسنج.</p><div class="relevance">${FIELDS.slice(0,4).map(t=>badge(t,'grey')).join('')}</div><div class="form-actions"><button class="button button-primary" data-action="new-research">+ ثبت پژوهش</button><button class="button button-outline" data-nav="research">مشاهدهٔ دفتر</button></div></div></section>`;
}
function renderCheck(d,slot,short=false){const key=slotKey(d.day,slot),checked=!!state.checks[key];const opts={morning:{time:'۰۶:۰۰–۰۷:۰۰',title:'مرور سبک + انگلیسی علمی (۶۰ دقیقه)',desc:'بازیابی دانسته‌های گذشته و خواندن کوتاه'},main:{time:'۱۴:۰۰–۱۵:۱۰',title:'ریاضی ۲۰ دقیقه + پایتون ۴۵ دقیقه + ۵ دقیقه استراحت',desc:'مطالعهٔ مرحله‌ای همراه با تمرین و ثبت ارزیابی'},evening:{time:'۱۹:۰۰–۲۱:۳۰',title:d.evening,desc:'۲ ساعت مطالعهٔ اصلی + ۳۰ دقیقه اختیاری'}};let o=opts[slot];return `<div class="check-line ${checked?'done':''}"><input type="checkbox" id="check-${d.day}-${slot}" data-action="slot-check" data-day="${d.day}" data-slot="${slot}" ${checked?'checked':''}><label for="check-${d.day}-${slot}"><strong>${cleanText(o.title)}</strong><small>${o.time}${short?'':' · '+o.desc}</small></label></div>`}
function renderCourse(t){const c=courseOf(t),done=state.completed[t].length,n=nextLesson(t),cap=t==='python'?`<div class="notice warning">سقف برنامهٔ پایتون: روزانه حداکثر ۶۰ دقیقهٔ ثبت‌شده. امروز ${dayMinutes(t)} دقیقه ثبت شده است. این سقف برای ثبت فعالیت در سایت کنترل می‌شود، نه زمان واقعی خارج از سایت.</div>`:'<div class="notice">ساعت پیشنهادی ریاضی: هر روز ۱۴:۰۰ تا ۱۴:۲۰. بعد از فهم و تمرین، گام بعد باز می‌شود.</div>';
 return `<div class="intro"><div><h2>${c.icon} ${c.name}</h2><p>${c.description}</p></div><div class="intro-stats"><strong>${progress(t)}٪</strong><span class="mini muted">${done} از ${c.lessons.length} درس</span></div></div>${pctBar(progress(t))}${cap}<div class="section-head" style="margin-top:25px"><div><h2>نقشهٔ مراحل</h2><p>برای بازشدن گام بعد: ۵ پاسخ درست از ۵ سؤال + توضیح چرایی و چگونگی ثبت‌شده.</p></div><button class="button button-primary" data-action="open-lesson" data-track="${t}" data-id="${n.id}">ادامهٔ مسیر</button></div><div class="lesson-list">${c.lessons.map((l,i)=>{let isU=unlocked(t,i),isP=passed(t,l.id),isN=l.id===n.id;return `<article class="lesson-item ${!isU?'locked':isN?'active-lesson':''}"><div class="lesson-item-header"><div class="lesson-number">${isP?'✓':!isU?'🔒':i+1}</div><div><h3>${cleanText(l.title)}</h3><span class="level-tag">${cleanText(l.level)} · ${l.minutes} دقیقه</span></div></div><p>${cleanText(l.goal)}</p><div class="lesson-item-footer">${isP?badge('تأییدشده','green'):!isU?badge('منتظر پیش‌نیاز','grey'):badge('آمادهٔ یادگیری','amber')}<button class="button button-${isU?'outline':'muted'} button-sm" data-action="open-lesson" data-track="${t}" data-id="${l.id}" ${!isU?'disabled':''}>${isP?'مرور':'ورود به درس'}</button></div></article>`}).join('')}</div>`;
}
function demoKey(t,id){return t+'|'+id}
function activeStep(t,id){const n=Number(state.lessonDrafts[demoKey(t,id)]?.step||0);const lesson=COURSE[t].lessons.find(l=>l.id===id);return clamp(n,0,lesson.demo.length-1)}
function renderGraph(){const x=Number(state.lessonDrafts['math|ma05']?.graphX??3),y=2*x+1,px=220+x*35,py=95-y*8;return `<div class="graph-shell"><strong class="small">آزمایش تعاملی: ورودی x را جابه‌جا کن و نقطهٔ تابع را ببین.</strong><svg id="func-graph" viewBox="0 0 440 190" role="img" aria-label="نمودار تابع y مساوی ۲x به علاوهٔ ۱"><defs><pattern id="graph-grid" width="35" height="19" patternUnits="userSpaceOnUse"><path d="M 35 0 L 0 0 0 19" fill="none" stroke="#e0eaf0" stroke-width="1"/></pattern></defs><rect width="440" height="190" fill="url(#graph-grid)"/><path d="M220 5 V185 M5 95 H435" fill="none" stroke="#8ba7b1" stroke-width="1.2"/><path d="M62.5 159 L377.5 15" fill="none" stroke="#168f83" stroke-width="3" stroke-linecap="round"/><circle id="func-point" cx="${px}" cy="${py}" r="7" fill="#e79c46" stroke="white" stroke-width="3"/></svg><div class="graph-controls"><span id="graph-output">x = ${x} ← y = ${y}</span><input aria-label="تغییر ورودی x" type="range" min="-4" max="4" step="1" value="${x}" data-action="graph-x"></div></div>`}
function renderLesson(){const {track:t,id}=activeLesson||state.lastPlace;const c=COURSE[t],i=c.lessons.findIndex(l=>l.id===id);if(!c||i<0||!unlocked(t,i)){navigate(t||'dashboard');return ''}const l=c.lessons[i],st=activeStep(t,id),d=l.demo[st],key=demoKey(t,id),prior=state.assessments[key],remaining=t==='python'?60-dayMinutes('python'):999,dayCapReached=t==='python'&&remaining<=0;const recordedNote=state.notes[key]||'';const draft=state.lessonDrafts[key]||{};
 return `<div class="crumb"><button data-nav="${t}">${cleanText(c.name)}</button><span>‹</span><span>${cleanText(l.level)}</span></div><section class="lesson-header"><div><div>${passed(t,id)?badge('این مرحله تأیید شده','green'):badge('مرحلهٔ باز','amber')} ${badge(l.minutes+' دقیقهٔ پیشنهادی','grey')}</div><h2>${cleanText(l.title)}</h2><p>${cleanText(l.goal)}</p></div><button class="button button-outline" data-nav="${t}">بازگشت به نقشه</button></section>
 <div class="lesson-layout"><div class="col-stack"><section class="card"><div class="card-title"><h3>۱. مدل چرایی و چگونگی</h3>${badge('درک مفهومی')}</div><p>${cleanText(l.concept)}</p><div class="notice success">ذهنی دنبال کن: چه چیزی وارد می‌شود؟ کدام عمل اتفاق می‌افتد؟ چه چیز در حافظه یا نتیجه عوض می‌شود؟</div><h4>نمونهٔ اجرایی</h4><div class="codebox">${l.example.split('\n').map((line,j)=>`<div class="code-line ${j===d[6]?'selected':''}">${cleanText(line)}</div>`).join('')}</div><div class="stepper-controls"><button class="button button-outline button-sm" data-action="demo-next" ${st===l.demo.length-1?'disabled':''}>گام بعدی ←</button><div class="step-dots">${l.demo.map((v,j)=>`<span class="step-dot ${j===st?'on':''}"></span>`).join('')}</div><button class="button button-outline button-sm" data-action="demo-prev" ${st===0?'disabled':''}>→ گام قبل</button></div><div class="machine"><div class="machine-node"><small>ورودی / وضعیت اولیه</small><strong>${cleanText(d[0])}</strong></div><div class="machine-arrow">←</div><div class="machine-node"><small>فرایند</small><strong>${cleanText(d[2])}</strong></div><div class="machine-arrow">←</div><div class="machine-node"><small>حاصل</small><strong>${cleanText(d[3])}</strong></div></div><div class="step-annotation"><strong>گام ${st+1} از ${l.demo.length}:</strong> ${cleanText(d[1])}<div class="memory-chips"><span class="memory-chip"><b>وضعیت:</b> ${cleanText(d[4])}</span>${d[5]?`<span class="memory-chip"><b>خروجی:</b> ${cleanText(d[5])}</span>`:''}</div></div>${l.graph?renderGraph():''}</section>
 <section class="card"><div class="card-title"><h3>۲. مثال حل‌شده</h3>${badge('گام‌به‌گام','grey')}</div><ol class="worked">${l.worked.map(x=>`<li>${cleanText(x)}</li>`).join('')}</ol></section>
 <section class="card"><div class="card-title"><h3>۳. ارزیابی تسلط</h3>${badge('۳ سؤال + توضیح چرایی و چگونگی','amber')}</div><p class="small muted">این آزمون پاسخ‌های بسته را می‌سنجد؛ کیفیت توضیح آزاد باید با بازبینی خودت یا مربی بررسی شود. یک پاسخ نادرست به معنی نیاز به تکرار این مرحله است.</p><form data-form="assessment">${l.qs.map((q,j)=>`<div class="question"><strong>سؤال ${j+1}. ${cleanText(q[0])}</strong>${q[1].map((option,k)=>`<label class="choice"><input type="radio" name="q${j}" value="${k}" ${Number(draft['q'+j])===k&&draft['q'+j]!==undefined?'checked':''} required> ${cleanText(option)}</label>`).join('')}${prior?`<div class="feedback ${Number(prior.answers[j])===q[2]?'good':'bad'}">${Number(prior.answers[j])===q[2]?'✓ پاسخ درست':'✕ نیاز به مرور'} — ${cleanText(q[3])}</div>`:''}</div>`).join('')}
 <label class="form-label" for="causal">توضیح چرایی و چگونگی با زبان خودت (حداقل ۲۰ نویسه)</label><textarea id="causal" name="causal" class="textarea" minlength="20" placeholder="ورودی چه بود؟ چه تغییری رخ داد؟ چرا خروجی این شد؟" required>${cleanText(draft.causal||'')}</textarea><div class="counter">ارزیابی ماشینیِ متن آزاد انجام نمی‌شود؛ ثبت توضیح، فرصت بازاندیشی است.</div>
 <div class="form-grid" style="margin-top:14px"><div><label class="form-label">زمان واقعی این جلسه (دقیقه)</label><input class="field" type="number" name="minutes" min="1" max="${t==='python'?Math.max(1,remaining):180}" value="${Math.min(Number(draft.minutes||l.minutes),t==='python'?Math.max(1,remaining):180)}" required></div><div><label class="form-label">یادداشت کوتاه برای این جلسه (اختیاری)</label><input class="field" name="sessionNote" placeholder="چه چیزی برایم روشن شد؟" value="${cleanText(draft.sessionNote||'')}"></div></div>${dayCapReached?`<div class="notice warning">سقف ۶۰ دقیقهٔ پایتون امروز پر شده؛ ثبت جلسهٔ جدید برای امروز مجاز نیست. یادداشت‌ها و شبیه‌ساز همچنان بازند.</div>`:''}<div class="form-actions"><button class="button button-primary" type="submit" ${dayCapReached?'disabled':''}>بررسی پاسخ و ثبت جلسه</button><button class="button button-outline" type="button" data-action="reset-questions">پاک‌کردن پاسخ‌های فعلی</button></div></form>
 ${prior?`<div class="notice ${prior.passed?'success':'warning'}"><strong>آخرین نتیجه: ${prior.score} از ۳ درست • ${prior.passed?'مرحله تأیید شد':'نیاز به تمرین دوباره'}</strong><div> ${prior.passed?'می‌توانی مرحلهٔ بعد را شروع کنی.':'مدل را دوباره حرکت بده و سپس ارزیابی را تکرار کن.'}</div>${prior.passed&&i<c.lessons.length-1?`<button class="button button-teal" style="margin-top:9px" data-action="open-lesson" data-track="${t}" data-id="${c.lessons[i+1].id}">گام بعدی ←</button>`:''}</div>`:''}
 </section></div>
 <aside class="col-stack"><section class="card"><div class="card-title"><h3>یادداشت زندهٔ این مفهوم</h3>${badge('ذخیره در مرورگر','grey')}</div><p class="small muted">هر کشف، سؤال یا شبیه‌سازی ذهنی را ثبت کن؛ هنگام بازگشت به همین درس بازیابی می‌شود.</p><textarea class="textarea" rows="7" data-action="lesson-note" placeholder="مدل ذهنی من: ...">${cleanText(recordedNote)}</textarea><div class="form-actions"><button class="button button-muted" data-action="save-note">ذخیره یادداشت</button><button class="button button-outline" data-action="manual-session">ثبت مرور بدون آزمون</button></div></section>
 <section class="card"><div class="card-title"><h3>نقشهٔ تسلط</h3></div><div class="progress-row"><strong class="small">${c.name}</strong><span class="small">${progress(t)}٪</span></div>${pctBar(progress(t))}<p class="small muted" style="margin-top:13px">${(state.completed[t]||[]).length} مرحله از ${c.lessons.length} مرحله تأیید شده است.</p><hr class="sep"><h4>قانون عبور به گام بعد</h4><p class="small muted">۱. فهم مدل پویا؛ ۲. حل درست هر پنج سؤال؛ ۳. ثبت توضیح شخصی. بدون قبولی، گام بعد قفل می‌ماند.</p>${t==='python'?`<div class="notice warning">پایتون امروز: ${dayMinutes(t)} / ۶۰ دقیقهٔ ثبت‌شده</div>`:''}</section>
 <section class="card"><h3>بازگشت به آخرین وضعیت</h3><p class="small muted">شمارهٔ گام نمایش، پاسخ‌های ذخیره‌شده و یادداشت این درس روی همین مرورگر باقی می‌مانند.</p><div class="muted-box small">${passed(t,id)?'✓ مرحلهٔ تأییدشده':'○ مرحلهٔ در جریان'} • ${cleanText(l.level)}</div></section></aside></div>`;
}
function renderWeekly(){const done=Object.keys(state.checks).filter(k=>k.startsWith(weekKey()+'|')&&state.checks[k]).length;return `<div class="intro"><div><h2>هفته‌ای برای ساختن پایه‌های عمیق</h2><p>برنامهٔ پیشنهادی ثابت: ۱ ساعت صبح، جلسه‌های اصلی از ۱۴:۰۰، و ۲ ساعت مطالعهٔ عصر همراه با ۳۰ دقیقهٔ اختیاری. پایتون روزانه ۴۵ دقیقه است و سقف ثبت آن ۶۰ دقیقه.</p></div><div class="intro-stats"><strong>${Math.round(done/21*100)}٪</strong><span class="mini muted">${done} از ۲۱ بخش</span></div></div>${pctBar(Math.round(done/21*100))}<div class="notice">این برنامه چرخهٔ هفتگی است و برای پیگیری دستی طراحی شده؛ تیک‌های هر هفته مستقل‌اند. اعلان خودکار یا تقویم آنلاین ندارد.</div><section class="section-head"><div><h2>از ${faDate(weekStart())} تا ${faDate(getDayDate(5))}</h2><p>سه بخش کوتاه و واقع‌بینانه در هر روز؛ عصر ۳۰ دقیقهٔ پایانی اختیاری است.</p></div><button class="button button-outline" data-action="manual-session">+ ثبت جلسهٔ مستقل</button></section><div class="week-board">${WEEK.map(d=>`<article class="day-card ${d.day===new Date().getDay()?'today':''}"><h3><span>${d.name} <span class="mini muted">${faDate(getDayDate(d.day),{month:'short',day:'numeric'})}</span></span>${d.day===new Date().getDay()?badge('امروز','green'):badge('برنامهٔ هفتگی','grey')}</h3>${renderCheck(d,'morning')}${renderCheck(d,'main')}${renderCheck(d,'evening')}<div class="today-note">تمرکز: ${cleanText(d.focus)}</div></article>`).join('')}</div>`}
function statusLabel(s){return STATUS.find(x=>x[0]===s)?.[1]||'در صف مطالعه'}
function researchCard(r){const chosen=compareIds.includes(r.id);const f=r.field||'دیگر';const hasUrl=!!safeHref(r.url);return `<article class="research-card" data-research-card="${cleanText(r.id)}" data-search="${cleanText((r.title+' '+f+' '+r.summary).toLowerCase())}" data-status="${cleanText(r.status)}"><div class="tagline">${badge(f)}${badge(statusLabel(r.status),'grey')}${r.riskLevel==='high'?badge('هشدار ریسک بالا','red'):''}</div><h3>${cleanText(r.title)}</h3><p>${cleanText((r.summary||r.method||'چکیده یا روش هنوز ثبت نشده است.').slice(0,160))}</p><div class="mini muted">تاریخ انتشار: ${r.publicationDate?faDate(r.publicationDate):'نامشخص'} • ${hasUrl?`<a href="${cleanText(safeHref(r.url))}" target="_blank" rel="noopener noreferrer">منبع اصلی ↗</a>`:'منبع ندارد'}</div><div class="research-footer"><label class="choice" style="padding:0"><input type="checkbox" data-action="compare-check" data-id="${cleanText(r.id)}" ${chosen?'checked':''}> مقایسه</label><div style="display:flex;gap:5px"><button class="button button-outline button-sm" data-action="edit-research" data-id="${cleanText(r.id)}">ویرایش و بررسی</button><button class="button button-danger button-sm" title="حذف پرونده" data-action="delete-research" data-id="${cleanText(r.id)}">✕</button></div></div></article>`}
function renderResearch(){const filtered=state.research.filter(r=>(!researchFilter||r.status===researchFilter)&&(!searchText||(r.title+' '+r.field+' '+r.summary).toLowerCase().includes(searchText.toLowerCase()))).slice().sort((a,b)=>new Date(b.updated||b.created)-new Date(a.updated||a.created));return `<div class="intro"><div><h2>دفتر شواهد، نه فقط فهرست مقاله‌ها</h2><p>برای پژوهش‌های کوانتومی–زیستی–آنالوگ–ایجنتیک، روش آزمایش و خطر بیش‌برازش یا نشت داده را مستند کن؛ سپس دو پژوهش را بندبه‌بند مقایسه کن.</p></div><div class="intro-stats"><strong>${state.research.length}</strong><span class="mini muted">پروندهٔ ثبت‌شده</span></div></div><div class="notice">سایت مقاله‌ها را خودکار واکشی یا اعتبارسنجی نمی‌کند. ارزش‌گذاری پژوهش بر اساس اطلاعاتی است که خودت از منابع معتبر ثبت و بررسی می‌کنی.</div><div class="research-toolbar"><input class="field" type="search" id="research-search" data-action="research-search" placeholder="جست‌وجو در عنوان، حوزه و خلاصه..." value="${cleanText(searchText)}"><select class="select-field" data-action="research-filter"><option value="">همهٔ وضعیت‌ها</option>${STATUS.map(x=>`<option value="${x[0]}" ${researchFilter===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><button class="button button-primary" data-action="new-research">+ ثبت پژوهش</button><button class="button button-outline" data-action="compare-now" ${compareIds.length!==2?'disabled':''}>مقایسه (${compareIds.length}/۲)</button></div><div class="research-grid" id="research-list">${filtered.length?filtered.map(researchCard).join(''):`<div class="empty" style="grid-column:1/-1"><div class="empty-symbol">◉</div><h3>هنوز پروندهٔ منطبق وجود ندارد</h3><p>با عنوان مقاله، نشانی منبع، روش، داده و شواهد شروع کن. هر پرونده بعداً قابل ویرایش و مقایسه است.</p><button class="button button-primary" data-action="new-research">ساخت اولین پرونده</button></div>`}</div>`}
function field(name,label,value='',type='text',extra=''){return `<div class="form-group"><label class="form-label" for="rf-${name}">${label}</label><input class="field" id="rf-${name}" name="${name}" type="${type}" value="${cleanText(value)}" ${extra}></div>`}
function area(name,label,value='',placeholder=''){return `<div class="form-group form-full"><label class="form-label" for="rf-${name}">${label}</label><textarea class="textarea" id="rf-${name}" name="${name}" rows="3" placeholder="${cleanText(placeholder)}">${cleanText(value)}</textarea></div>`}
function optSelect(name,label,opts,value){return `<div class="form-group"><label class="form-label" for="rf-${name}">${label}</label><select class="select-field" id="rf-${name}" name="${name}">${opts.map(([v,l])=>`<option value="${cleanText(v)}" ${v===(value||'')?'selected':''}>${cleanText(l)}</option>`).join('')}</select></div>`}
function renderResearchEdit(){const r=activeResearch?state.research.find(x=>x.id===activeResearch):null;return `<div class="crumb"><button data-nav="research">دفتر پژوهش</button><span>‹</span><span>${r?'ویرایش پرونده':'پروندهٔ جدید'}</span></div><div class="intro"><div><h2>${r?'بازبینی مستندات پژوهش':'ثبت یک پژوهش واقعی'}</h2><p>دادهٔ مجهول را خالی بگذار، نه اینکه حدس بزنی. روش ارزیابی و خطر نشت داده در کنار نتایج اهمیت دارند.</p></div></div><form data-form="research" class="card"><div class="section-head"><div><h2>شناسنامه و منبع</h2><p>نشانی مقاله یا صفحهٔ رسمی پژوهش را بنویس.</p></div></div><div class="form-grid">${field('title','عنوان دقیق پژوهش *',r?.title,'text','required')}${optSelect('field','حوزهٔ اصلی',FIELDS.map(f=>[f,f]),r?.field||'کوانتومی')}${field('url','پیوند منبع (https://...) *',r?.url,'url','required placeholder="https://..."')}${field('publicationDate','تاریخ انتشار',r?.publicationDate||'','date')}${optSelect('status','مرحلهٔ مطالعه',STATUS,r?.status||'queue')}${optSelect('riskLevel','ارزیابی اولیهٔ ریسک', [['unknown','نامشخص / بررسی نشده'],['low','کم با شواهد'],['medium','متوسط'],['high','زیاد / هشدار']],r?.riskLevel||'unknown')}${area('summary','مسئله و ادعای پژوهش',r?.summary,'دقیقاً کدام مسئله حل شده و ادعای اصلی چیست؟')}</div><hr class="sep"><div class="section-head"><div><h2>روش‌شناسی و شواهد</h2><p>برخلاف چکیده، شرایط آزمایش را بازسازی‌پذیر ثبت کن.</p></div></div><div class="form-grid">${area('method','روش آزمایش و معماری',r?.method,'طرح آزمایش، مدل، متغیرهای کنترل، محیط اجرا')}${area('dataset','داده‌ها، اندازه نمونه و تقسیم داده',r?.dataset,'آموزش/اعتبارسنجی/آزمون، توزیع زمانی و استقلال نمونه‌ها')}${area('baselines','روش‌های مبنا و مقایسهٔ منصفانه',r?.baselines,'با چه مدل‌های کلاسیک/کوانتومی/آنالوگ مقایسه شده؟')}${area('evidence','شواهد کمی، عدم قطعیت و نتایج',r?.evidence,'اندازه اثر، خطای تخمین، بازه اطمینان، بذر تصادفی، تکرارها')}${area('limitations','محدودیت‌ها و تهدیدهای اعتبار',r?.limitations,'اندازه نمونه، تعمیم، منابع محاسباتی، وابستگی به شرایط')}${area('leakage','بیش‌برازش، نشت داده و راه آزمون',r?.leakage,'آیا تست مستقل؟ انتخاب مدل با دادهٔ آزمون؟ تداخل زمان/افراد؟')}${area('prereqs','پیش‌نیازهای علمی برای فهم یا بازتولید',r?.prereqs,'ریاضی، فیزیک، زیست، برنامه‌نویسی، ابزار')}${area('application','کاربرد عملی برای مسیر پژوهشی من',r?.application,'چه ایده، مهارت یا آزمایشی برای پروژهٔ بلندمدت به‌دست می‌آید؟')}${area('replication','طرح بازتولید و گام آزمایشی بعدی',r?.replication,'کد/داده باز است؟ چه آزمایش کوچکی از عهده‌ام برمی‌آید؟')}${area('notes','یادداشت انتقادی و سؤال‌های باز',r?.notes,'چه چیزی هنوز روشن نیست؟')}${field('minutes','زمان کار روی این پرونده (دقیقه؛ اختیاری)',0,'number','min="0" max="600"')}
 </div><div class="notice warning">این فرم به‌معنای تأیید علمی مقاله نیست. ریسک «کم» تنها با شواهد مناسب باید انتخاب شود؛ اگر داده کافی نیست «نامشخص» را حفظ کن.</div><div class="form-actions"><button class="button button-primary" type="submit">${r?'ذخیرهٔ ویرایش':'ثبت پرونده'}</button><button class="button button-outline" type="button" data-nav="research">انصراف</button></div></form>`}
function renderCompare(){const rs=compareIds.map(id=>state.research.find(x=>x.id===id));if(rs.length!==2||rs.some(x=>!x)){navigate('research');return ''}const rows=[['حوزهٔ پژوهش','field'],['تاریخ انتشار','publicationDate'],['وضعیت بررسی','status'],['مسئله و ادعا','summary'],['روش آزمایش','method'],['داده و روش تقسیم','dataset'],['خط مبنا / مقایسه','baselines'],['شواهد و عدم قطعیت','evidence'],['محدودیت‌ها','limitations'],['ریسک بیش‌برازش و نشت','leakage'],['درجهٔ ریسک','riskLevel'],['پیش‌نیازها','prereqs'],['کاربرد عملی','application'],['امکان بازتولید','replication'],['یادداشت انتقادی','notes']];const level={unknown:'نامشخص',low:'کم',medium:'متوسط',high:'زیاد'};function val(r,f){if(!r[f])return '<span class="muted">ثبت نشده</span>';if(f==='status')return cleanText(statusLabel(r[f]));if(f==='riskLevel')return cleanText(level[r[f]]||r[f]);if(f==='publicationDate')return cleanText(faDate(r[f]));return nl(r[f])};const gaps=rs.map(r=>['dataset','baselines','evidence','leakage'].filter(f=>!(r[f]||'').trim()).length);return `<div class="crumb"><button data-nav="research">دفتر پژوهش</button><span>‹</span><span>مقایسه</span></div><div class="intro"><div><h2>مقایسهٔ انتقادی دو پژوهش</h2><p>نه بر اساس جذابیت عنوان، بلکه بر اساس روش، داده، شواهد و تکرارپذیری.</p></div><button class="button button-outline" data-nav="research">بازگشت به پرونده‌ها</button></div><div class="notice ${gaps[0]||gaps[1]?'warning':'success'}">کامل‌بودن مستندات کلیدی: پژوهش اول ${4-gaps[0]}/۴، پژوهش دوم ${4-gaps[1]}/۴ (داده، مبنا، شواهد و ریسک نشت). <strong>این عدد امتیاز کیفیت علمی نیست.</strong></div><div class="card" style="overflow:auto"><table class="compare-table"><thead><tr><th>معیار</th>${rs.map(r=>`<td><h3>${cleanText(r.title)}</h3>${safeHref(r.url)?`<a href="${cleanText(safeHref(r.url))}" target="_blank" rel="noopener noreferrer">مشاهدهٔ منبع</a>`:'منبع ثبت نشده'}</td>`).join('')}</tr></thead><tbody>${rows.map(([label,prop])=>`<tr><th>${label}</th>${rs.map(r=>`<td>${val(r,prop)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">برای نتیجه‌گیری بهتر، روشِ تقسیم داده، مقایسه با خط مبنا، تکرار مستقل و هزینهٔ محاسباتی را کنار هم قضاوت کن. اختلاف نتایج بدون روش همسان به معنی برتری قطعی نیست.</div>`}
function renderSkills(){return `<div class="intro"><div><h2>نقشهٔ مهارت‌ها و شواهد پیشرفت</h2><p>سطح‌های خودارزیابی از صفر تا پنج هستند؛ با هر ارتقا، سند یا تمرینی که آن را پشتیبانی می‌کند ثبت کن. پیشرفت درسیِ تأییدشده جدا از خودارزیابی نمایش داده می‌شود.</p></div></div><div class="grid-main"><div class="card"><div class="card-title"><h3>پیشرفت آزمون‌های مرحله‌ای</h3></div>${['python','math'].map(t=>`<div class="track-card"><div class="progress-row"><strong>${COURSE[t].name}</strong><span>${progress(t)}٪</span></div>${pctBar(progress(t))}<div class="mini muted" style="margin-top:10px">${state.completed[t].length} درس از ${COURSE[t].lessons.length} با آزمون تأییدشده</div></div>`).join('')}</div><div class="card"><div class="card-title"><h3>مقیاس خودارزیابی</h3></div><p class="small">۰: آشنا نیستم • ۱: شناخت اولیه • ۲: می‌توانم توضیح بدهم • ۳: مسئلهٔ پایه را حل می‌کنم • ۴: مستقل پیاده می‌کنم • ۵: نقد/پژوهش و بازتولید می‌کنم.</p><div class="notice warning">سطح ۵ ادعای مهارت حرفه‌ای نیست؛ شواهد مشخص لازم دارد. این سطح‌ها خوداظهاری‌اند.</div></div></div><section class="section"><div class="section-head"><h2>مهارت‌های قابل پیگیری</h2><p>روی «ثبت شواهد» کلیک کن.</p></div><div class="skill-list">${SKILLS.map(([id,title,desc])=>{let s=state.skills[id]||{level:0,evidence:''};return `<div class="skill-card"><div class="top"><h3>${cleanText(title)}</h3>${badge('سطح '+Number(s.level||0),'')}</div><div class="skill-levels">${[1,2,3,4,5].map(i=>`<span class="level-box ${i<=Number(s.level||0)?'filled':''}"></span>`).join('')}</div><p>${cleanText(desc)}</p><div class="mini muted" style="min-height:27px;margin-bottom:11px">${s.evidence?cleanText(s.evidence.slice(0,105)):'هنوز شاهدی ثبت نشده است.'}</div><button class="button button-outline button-sm" data-action="edit-skill" data-id="${id}">ثبت سطح و شواهد</button></div>`}).join('')}</div></section>`}
let historyFilter='';
function sessionTitle(s){if(s.title)return s.title;if(COURSE[s.track]&&s.lessonId)return COURSE[s.track].lessons.find(l=>l.id===s.lessonId)?.title||COURSE[s.track].name;return {research:'مطالعهٔ پژوهشی',weekly:'مطالعهٔ مستقل',python:'پایتون',math:'ریاضی'}[s.track]||'فعالیت مطالعاتی'}
function renderHistory(){const sess=state.sessions.filter(s=>!historyFilter||s.track===historyFilter).slice().sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp));const notes=Object.entries(state.notes).filter(([k,v])=>v?.trim());return `<div class="intro"><div><h2>هر قدم ثبت می‌شود، نه فراموش</h2><p>جلسه‌ها، زمان واقعیِ اعلام‌شده، نتیجهٔ ارزیابی و یادداشت‌های هر درس را مرور کن. می‌توانی از ثبت‌های قبلی به همان مفهوم برگردی.</p></div><div class="intro-stats"><strong>${state.sessions.length}</strong><span class="mini muted">جلسهٔ ثبت‌شده</span></div></div><div class="research-toolbar"><select class="select-field" data-action="history-filter" style="max-width:240px"><option value="">همهٔ موضوع‌ها</option>${[['python','پایتون'],['math','ریاضی'],['research','پژوهش'],['weekly','مطالعهٔ مستقل']].map(x=>`<option value="${x[0]}" ${historyFilter===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><button class="button button-primary" data-action="manual-session">+ ثبت جلسه جدید</button><button class="button button-outline" data-action="export">دریافت تمام داده‌ها</button><button class="button button-outline" data-action="import">بازیابی پشتیبان</button></div><section class="card"><div class="card-title"><h3>سوابق جلسات</h3>${badge(sess.length+' مورد','grey')}</div>${sess.length?`<div class="history-row header"><span>موضوع</span><span>زمان ثبت</span><span>مدت</span><span>نتیجه</span><span>عملیات</span></div>${sess.map(s=>`<div class="history-row"><div><strong>${cleanText(sessionTitle(s))}</strong><div class="history-notes" title="${cleanText(s.note||'')}">${cleanText(s.note||s.kind||'بدون یادداشت')}</div></div><div class="mini muted">${faDate(s.timestamp)}</div><div>${Number(s.minutes)||0} دقیقه</div><div>${s.score!==null&&s.score!==undefined?badge(s.score+'/'+(s.totalQuestions||(s.track==='science'?5:3)),s.passed?'green':'amber'):badge(s.kind||'ثبت‌شده','grey')}</div><button class="button button-outline button-sm" data-action="history-open" data-id="${cleanText(s.id)}">جزئیات</button></div>`).join('')}`:`<div class="empty"><div class="empty-symbol">◷</div><p>هنوز موردی در این فیلتر ثبت نشده است.</p></div>`}</section><section class="section"><div class="section-head"><h2>یادداشت‌های مفهومی</h2><p>${notes.length} یادداشت مستقل</p></div>${notes.length?`<div class="split-cards">${notes.map(([k,v])=>{let [t,id]=k.split('|');let l=COURSE[t]?.lessons.find(x=>x.id===id);if(!l)return '';return `<div class="card"><h3>${cleanText(l.title)}</h3><p class="small note-text">${cleanText(v.slice(0,400))}${v.length>400?'…':''}</p><button class="button button-outline button-sm" data-action="open-lesson" data-track="${t}" data-id="${id}">باز کردن یادداشت و درس</button></div>`}).join('')}</div>`:`<div class="empty"><p>یادداشت مفهومی هنوز ثبت نشده است.</p></div>`}</section>${(state.skillHistory||[]).length?`<section class="section card"><h3>آخرین تغییرات خودارزیابی</h3>${state.skillHistory.slice(-7).reverse().map(h=>`<p class="small"><strong>${cleanText(SKILLS.find(s=>s[0]===h.skill)?.[1]||h.skill)}</strong> · سطح ${h.level} · ${faDate(h.date)} — ${cleanText(h.evidence?.slice(0,90)||'بدون شاهد')}</p>`).join('')}</section>`:''}`}
function openLesson(t,id){const c=COURSE[t];if(!c)return;const idx=c.lessons.findIndex(l=>l.id===id);if(idx<0||!unlocked(t,idx)){showToast('ابتدا مرحلهٔ پیش‌نیاز را با موفقیت تمام کن.');return}activeLesson={track:t,id};state.lastPlace={track:t,id};save();navigate('lesson')}
function openModal(inner){document.getElementById('modal-host').innerHTML=`<div class="modal-layer" data-action="modal-backdrop"><div class="modal" role="dialog" aria-modal="true">${inner}</div></div>`}
function closeModal(){document.getElementById('modal-host').innerHTML=''}
function modalHead(title){return `<div class="modal-head"><h2>${cleanText(title)}</h2><button class="modal-x" data-action="close-modal" aria-label="بستن">×</button></div>`}
function manualSessionModal(){let pre=activeLesson?.track||'python';openModal(`<form data-form="manual-session">${modalHead('ثبت جلسهٔ مطالعه یا مرور')}<p class="small muted">زمان را بر اساس مطالعهٔ واقعی وارد کن. ثبتِ پایتون بیش از ۶۰ دقیقه در یک روز پذیرفته نمی‌شود.</p><div class="form-grid"><div><label class="form-label">موضوع</label><select class="select-field" name="track" id="manual-track"><option value="python" ${pre==='python'?'selected':''}>پایتون</option><option value="math" ${pre==='math'?'selected':''}>ریاضی</option><option value="research">پژوهش</option><option value="weekly">مطالعهٔ مستقل</option></select></div><div><label class="form-label">زمان واقعی (دقیقه)</label><input class="field" name="minutes" type="number" value="20" min="1" max="600" required></div><div class="form-full"><label class="form-label">عنوان جلسه</label><input class="field" name="title" value="" placeholder="مثلاً مرور انتساب یا نقد مقاله" required></div><div class="form-full"><label class="form-label">یادداشت و دستاورد</label><textarea class="textarea" name="note" placeholder="چه چیزی آموختم و مرحلهٔ بعد چیست؟"></textarea></div></div><div class="form-actions"><button class="button button-primary" type="submit">ثبت جلسه</button><button class="button button-outline" type="button" data-action="close-modal">انصراف</button></div></form>`)}
function skillModal(id){const sk=SKILLS.find(x=>x[0]===id);if(!sk)return;let old=state.skills[id]||{level:0,evidence:''};openModal(`<form data-form="skill" data-skill="${id}">${modalHead('شواهد مهارت: '+sk[1])}<p class="small muted">ارتقا را زمانی انتخاب کن که بتوانی نمونه‌کار یا تمرین مرتبط ارائه بدهی.</p><label class="form-label">سطح خودارزیابی</label><select class="select-field" name="level">${[['0','۰ — آشنایی ندارم'],['1','۱ — شناخت اولیه'],['2','۲ — توضیح مفهومی'],['3','۳ — حل تمرین مستقل'],['4','۴ — اجرای پروژه'],['5','۵ — نقد علمی و بازتولید']].map(([v,l])=>`<option value="${v}" ${Number(v)===Number(old.level)?'selected':''}>${l}</option>`).join('')}</select><label class="form-label" style="margin-top:13px">شواهد، تمرین یا پیوند قابل ارجاع</label><textarea class="textarea" name="evidence" rows="5" placeholder="مثلاً در درس ... تمرین ... را بدون راهنما حل کردم.">${cleanText(old.evidence||'')}</textarea><div class="form-actions"><button class="button button-primary" type="submit">ثبت تغییر</button><button type="button" class="button button-outline" data-action="close-modal">انصراف</button></div></form>`)}
function historyModal(id){let s=state.sessions.find(x=>x.id===id);if(!s)return;openModal(`${modalHead('جزئیات جلسه')}<h3>${cleanText(sessionTitle(s))}</h3><p class="small muted">${faDate(s.timestamp)} • ${Number(s.minutes)||0} دقیقه • ${cleanText(s.kind||'جلسه')}</p>${s.score!==null&&s.score!==undefined?`<div class="notice ${s.passed?'success':'warning'}">نتیجه: ${s.score}/${s.totalQuestions||(s.track==='science'?5:3)} • ${s.passed?'گام تأیید شده':'به تکرار نیاز دارد'}</div>`:''}<h4>یادداشت جلسه</h4><div class="muted-box note-text">${cleanText(s.note||'یادداشتی ثبت نشده است.')}</div>${s.causal?`<h4 style="margin-top:17px">توضیح چرایی و چگونگی ثبت‌شده</h4><div class="muted-box note-text">${cleanText(s.causal)}</div>`:''}<div class="form-actions">${s.lessonId&&COURSE[s.track]?`<button class="button button-primary" data-action="open-lesson" data-track="${s.track}" data-id="${s.lessonId}">باز کردن درس</button>`:''}<button class="button button-outline" data-action="close-modal">بستن</button><button class="button button-danger" data-action="delete-session" data-id="${cleanText(s.id)}">حذف این ثبت</button></div>`)}
function exportBackup(){const data={...state,exportedAt:isoNow(),app:'madar-offline'};const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=`madar-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);showToast('نسخهٔ پشتیبان JSON دریافت شد. آن را جای امن نگه دار.')}
function importBackup(file){if(!file)return;if(file.size>5000000){showToast('فایل بزرگ‌تر از سقف ۵ مگابایت است.');return}const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(data?.schema!==1||!Array.isArray(data.sessions)||!Array.isArray(data.research)||!Array.isArray(data.completed?.python)||!Array.isArray(data.completed?.math)||typeof data.notes!=='object')throw Error('invalid');if(!confirm('بازیابی، اطلاعات موجود این مرورگر را با داده‌های فایل جایگزین می‌کند. ابتدا از اطلاعات فعلی پشتیبان گرفته‌ای؟'))return;state={...defaults(),...data,settings:{...defaults().settings,...data.settings}};state.completed.python=state.completed.python.filter(x=>COURSE.python.lessons.some(l=>l.id===x));state.completed.math=state.completed.math.filter(x=>COURSE.math.lessons.some(l=>l.id===x));save();compareIds=[];navigate('dashboard');showToast('پشتیبان بازیابی شد.')}catch(e){alert('فایل پشتیبان معتبر یا سازگار با نسخهٔ فعلی مَدار نیست.')}};reader.readAsText(file)}
function submitAssessment(form){const {track:t,id}=activeLesson||{};const l=COURSE[t]?.lessons.find(v=>v.id===id);if(!l)return;const fd=new FormData(form);const answers=l.qs.map((q,j)=>fd.get('q'+j));if(answers.some(a=>a===null)){showToast('به هر پنج سؤال جواب بده.');return}const causal=String(fd.get('causal')||'').trim();if(causal.length<20){showToast('توضیح چرایی و چگونگی را با دست‌کم ۲۰ نویسه ثبت کن.');return}let minutes=Number(fd.get('minutes'));if(!Number.isInteger(minutes)||minutes<1||minutes>180){showToast('مدت جلسه باید عدد معتبری به دقیقه باشد.');return}if(t==='python'&&dayMinutes('python')+minutes>60){showToast(`سقف پایتون ۶۰ دقیقه است؛ امروز فقط ${60-dayMinutes('python')} دقیقه ظرفیت ثبت باقی است.`);return}
 const correct=answers.reduce((sum,a,j)=>sum+(Number(a)===l.qs[j][2]?1:0),0),success=correct===l.qs.length;const key=demoKey(t,id);state.assessments[key]={answers:answers.map(Number),causal,score:correct,total:l.qs.length,passed:success,date:isoNow()};state.sessions.push({id:uid(),timestamp:isoNow(),date:today(),track:t,lessonId:id,kind:'ارزیابی مرحله‌ای',minutes,score:correct,passed:success,note:String(fd.get('sessionNote')||'').trim(),causal});state.lessonDrafts[key]={...(state.lessonDrafts[key]||{}),causal,minutes,sessionNote:String(fd.get('sessionNote')||'').trim(),...Object.fromEntries(answers.map((a,j)=>['q'+j,a]))};if(success&&!state.completed[t].includes(id)){state.completed[t].push(id);const idx=COURSE[t].lessons.findIndex(x=>x.id===id);if(idx<COURSE[t].lessons.length-1)state.lastPlace={track:t,id:COURSE[t].lessons[idx+1].id}}save();render();showToast(success?'آفرین! این مرحله تأیید شد و مرحلهٔ بعد باز است.':'نتیجه ثبت شد؛ پیش‌نیاز هنوز قفل است. مثال را مرور کن.')}
function submitResearch(form){const fd=new FormData(form),names=['title','field','url','publicationDate','status','riskLevel','summary','method','dataset','baselines','evidence','limitations','leakage','prereqs','application','replication','notes'];const obj={};names.forEach(n=>obj[n]=String(fd.get(n)||'').trim());if(!obj.title||!safeHref(obj.url)){showToast('عنوان و پیوند معتبر http/https ضروری است.');return}if(obj.title.length>450||obj.url.length>1500){showToast('عنوان یا نشانی بیش از حد طولانی است.');return}let mins=Number(fd.get('minutes')||0);if(!Number.isInteger(mins)||mins<0||mins>600){showToast('زمان پژوهش باید بین صفر و ۶۰۰ دقیقه باشد.');return}const old=activeResearch?state.research.find(x=>x.id===activeResearch):null;if(old){Object.assign(old,obj,{updated:isoNow()})}else{const r={...obj,id:uid(),created:isoNow(),updated:isoNow()};state.research.push(r);activeResearch=r.id}if(mins>0)state.sessions.push({id:uid(),timestamp:isoNow(),date:today(),track:'research',title:'بررسی: '+obj.title,minutes:mins,score:null,kind:'پژوهش',note:obj.notes||obj.summary});save();navigate('research');showToast('پروندهٔ پژوهش و تغییرات آن ذخیره شد.')}
function submitManual(form){const fd=new FormData(form),track=String(fd.get('track')),minutes=Number(fd.get('minutes')),title=String(fd.get('title')||'').trim();if(!['python','math','research','weekly'].includes(track)||!Number.isInteger(minutes)||minutes<1||minutes>600||!title){showToast('موضوع، عنوان و زمان معتبر وارد کن.');return}if(track==='python'&&dayMinutes('python')+minutes>60){showToast('سقف ثبت مطالعهٔ پایتون: ۶۰ دقیقه در روز.');return}state.sessions.push({id:uid(),timestamp:isoNow(),date:today(),track,title,minutes,kind:'جلسهٔ دستی',score:null,note:String(fd.get('note')||'').trim()});save();closeModal();render();showToast('جلسه با زمان و یادداشت ذخیره شد.')}
function submitSkill(form){let id=form.dataset.skill,level=Number(new FormData(form).get('level')),evidence=String(new FormData(form).get('evidence')||'').trim();if(!SKILLS.some(x=>x[0]===id)||!Number.isInteger(level)||level<0||level>5){showToast('سطح نامعتبر است.');return}if(level>=3&&evidence.length<10){showToast('برای سطح ۳ و بالاتر، دست‌کم ۱۰ نویسه شاهد ثبت کن.');return}state.skills[id]={level,evidence,updated:isoNow()};state.skillHistory=state.skillHistory||[];state.skillHistory.push({skill:id,level,evidence,date:isoNow()});save();closeModal();render();showToast('شواهد پیشرفت مهارتی ذخیره شد.')}
function updateResearchSearch(){const list=document.getElementById('research-list');if(!list)return;let cards=[...list.querySelectorAll('[data-research-card]')],visible=0;for(let c of cards){let r=state.research.find(x=>x.id===c.dataset.researchCard);let yes=r&&(!researchFilter||r.status===researchFilter)&&(!searchText||(r.title+' '+r.field+' '+r.summary).toLowerCase().includes(searchText.toLowerCase()));c.classList.toggle('hide',!yes);if(yes)visible++}if(!visible&&cards.length)list.insertAdjacentHTML('beforeend','<div class="empty search-none" style="grid-column:1/-1"><p>پژوهشی با این جست‌وجو یافت نشد.</p></div>');else list.querySelector('.search-none')?.remove()}
function handleClick(e){const el=e.target.closest('[data-action],[data-nav]');if(!el)return;if(el.dataset.nav){navigate(el.dataset.nav);return}const action=el.dataset.action;
 switch(action){
 case'open-lesson':closeModal();openLesson(el.dataset.track,el.dataset.id);break;
 case'demo-next':case'demo-prev':{let {track,id}=activeLesson,k=demoKey(track,id),d=state.lessonDrafts[k]||{};d.step=clamp(activeStep(track,id)+(action==='demo-next'?1:-1),0,COURSE[track].lessons.find(l=>l.id===id).demo.length-1);state.lessonDrafts[k]=d;save();render();break}
 case'new-research':activeResearch=null;navigate('researchEdit');break;
 case'edit-research':activeResearch=el.dataset.id;navigate('researchEdit');break;
 case'delete-research':if(confirm('این پروندهٔ پژوهش حذف شود؟ سوابق جلسات پژوهش به صورت جداگانه باقی می‌مانند.')){state.research=state.research.filter(x=>x.id!==el.dataset.id);compareIds=compareIds.filter(x=>x!==el.dataset.id);save();render();showToast('پرونده حذف شد.')}break;
 case'compare-now':if(compareIds.length===2)navigate('compare');break;
 case'manual-session':manualSessionModal();break;
 case'edit-skill':skillModal(el.dataset.id);break;
 case'history-open':historyModal(el.dataset.id);break;
 case'delete-session':if(confirm('این سابقهٔ جلسه حذف شود؟ تأیید درس و سایر سوابق دست‌نخورده می‌مانند.')){state.sessions=state.sessions.filter(x=>x.id!==el.dataset.id);save();closeModal();render();showToast('جلسه حذف شد.')}break;
 case'close-modal':closeModal();break;
 case'modal-backdrop':if(e.target===el)closeModal();break;
 case'export':exportBackup();break;
 case'import':document.getElementById('import-file').click();break;
 case'save-note':save();showToast('یادداشت مفهوم ذخیره شد.');break;
 case'reset-questions':{const key=demoKey(activeLesson.track,activeLesson.id);state.lessonDrafts[key]={step:activeStep(activeLesson.track,activeLesson.id)};delete state.assessments[key];save();render();showToast('پاسخ‌های تمرین پاک شدند؛ وضعیت تسلط قبلی حفظ شده است.');break}
 }
}
function handleChange(e){const el=e.target,action=el.dataset.action;
 if(action==='slot-check'){state.checks[slotKey(Number(el.dataset.day),el.dataset.slot)]=el.checked;save();render();return}
 if(action==='compare-check'){const id=el.dataset.id;if(el.checked){if(!compareIds.includes(id)&&compareIds.length===2){el.checked=false;showToast('برای مقایسه فقط دو پژوهش را انتخاب کن.');return}if(!compareIds.includes(id))compareIds.push(id)}else compareIds=compareIds.filter(x=>x!==id);render();return}
 if(action==='research-filter'){researchFilter=el.value;render();return}
 if(action==='history-filter'){historyFilter=el.value;render();return}
}
function handleInput(e){const el=e.target,action=el.dataset.action;
 if(action==='lesson-note'&&activeLesson){state.notes[demoKey(activeLesson.track,activeLesson.id)]=el.value;save();return}
 if(action==='research-search'){searchText=el.value;updateResearchSearch();return}
 if(action==='graph-x'){const x=Number(el.value),key='math|ma05';state.lessonDrafts[key]={...(state.lessonDrafts[key]||{}),graphX:x};save();const point=document.getElementById('func-point'),output=document.getElementById('graph-output');if(point){point.setAttribute('cx',String(220+x*35));point.setAttribute('cy',String(95-(2*x+1)*8))}if(output)output.textContent=`x = ${x} ← y = ${2*x+1}`;return}
 const form=el.closest('form[data-form="assessment"]');if(form&&activeLesson){const k=demoKey(activeLesson.track,activeLesson.id),d=state.lessonDrafts[k]||{};if(el.name)d[el.name]=el.value;state.lessonDrafts[k]=d;save()}
}
function handleSubmit(e){const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const formType=form.getAttribute('data-form');if(formType==='assessment')submitAssessment(form);if(formType==='research')submitResearch(form);if(formType==='manual-session')submitManual(form);if(formType==='skill')submitSkill(form)}
document.addEventListener('click',handleClick);document.addEventListener('change',handleChange);document.addEventListener('input',handleInput);document.addEventListener('submit',handleSubmit);
document.getElementById('mobile-menu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('import-file').addEventListener('change',e=>{importBackup(e.target.files?.[0]);e.target.value=''});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();


// v3.11: page navigation buttons do not change course data or stored progress.
document.addEventListener('click', function(event) {
  const trigger=event.target.closest('[data-scroll]');
  if(!trigger) return;
  const goDown=trigger.dataset.scroll==='bottom';
  const limit=Math.max(document.documentElement.scrollHeight,document.body.scrollHeight)-window.innerHeight;
  window.scrollTo({top:goDown ? Math.max(0,limit) : 0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
});
